                    cells.append((rr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc] and grid[nr][nc] == color:
                            seen[nr][nc] = True
                            q.append((nr, nc))
                objs.append((color, cells))
    counts = Counter(c for c, _ in objs)
    uniq = [(c, cells) for c, cells in objs if counts[c] == 1]
    if not uniq:
        return [row[:] for row in grid]
    # prefer non-rectangle template objects, then largest
    def is_rect(cells):
        rs = [r for r, c in cells]; cs = [c for r, c in cells]
        return len(cells) == (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)
    uniq_sorted = sorted(uniq, key=lambda x: (is_rect(x[1]), len(x[1])))
