    bg = cnt.most_common(1)[0][0]
    seen = [[False] * W for _ in range(H)]
    objs = []
    for r in range(H):
        for c in range(W):
            if not seen[r][c] and grid[r][c] != bg:
                color = grid[r][c]
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    rr, cc = q.popleft()
                    cells.append((rr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc] and grid[nr][nc] == color:
                            seen[nr][nc] = True
                            q.append((nr, nc))
                objs.append((color, cells))
    counts = Counter(c for c, _ in objs)
    uniq = [(c, cells) for c, cells in objs if counts[c] == 1]
    if not uniq:
        return [row[:] for row in grid]

    def fill(cells):
        rs = [r for r, c in cells]; cs = [c for r, c in cells]
        area = (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)
        return len(cells) / area

    # template: single-object color with sparsest (L-like) object
    tc, tcells = min(uniq, key=lambda x: (fill(x[1]), -len(x[1])))

    def norm(cells):
        mr = min(r for r, c in cells); mc = min(c for r, c in cells)
