        if c == tc:
            continue
        groups.setdefault(norm(cells), []).append(i)

    cands = []
    for k, idxs in groups.items():
        for i in range(len(idxs)):
            for j in range(i + 1, len(idxs)):
                cands.append((idxs[i], idxs[j]))
