        d = mindist(objs[i][1], objs[j][1])
        return (d, -min(len(objs[i][1]), len(objs[j][1])))

    i, j = min(cands, key=pair_key)
    di = mindist(objs[i][1], tcells)
    dj = mindist(objs[j][1], tcells)
    tgt = i if di >= dj else j
    out = [row[:] for row in grid]
    for r, c in objs[tgt][1]:
